private static void dfs(char[][] grid, boolean[][] visited, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || visited[i][j] || grid[i][j] == '*') {
        return;
    }

    visited[i][j] = true;

    dfs(grid, visited, i - 1, j, rows, cols); // up
    dfs(grid, visited, i + 1, j, rows, cols); // down
    dfs(grid, visited, i, j - 1, rows, cols); // left
    dfs(grid, visited, i, j + 1, rows, cols); // right
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula to calculate the maximum number of regions
    // when N triangles are added to the plane is:
    // R(N) = 2 + 3 * N + 2 * combinations(N, 2)
    // where combinations(N, 2) is the binomial coefficient N choose 2
    // which is calculated as N * (N - 1) / 2
    return 2 + 3 * N + 2 * (N * (N - 1) / 2);
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("The number of triangles cannot be negative.");
    }
    if (N == 0) {
        return 1; // No triangles, just the whole plane as one region
    }
    // The formula to calculate the maximum number of regions for N triangles
    // is derived from the fact that each new triangle can intersect with all previous ones
    // and create new regions.
    return 1 + N * (N + 1) / 2 + N * (N - 1) / 2;
}

