public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], visited, paths, n);
    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, boolean[][] visited, int[][] paths, int n) {
    if (x == endX && y == endY) {
        return true;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        if (path[0] == x && path[1] == y && !visited[path[2]][path[3]]) {
            if (dfs(path[2], path[3], endX, endY, visited, paths, n)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y && !visited[path[0]][path[1]]) {
            if (dfs(path[0], path[1], endX, endY, visited, paths, n)) {
                return true;
            }
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || paths == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0]][start[1]] = true;

    int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        for (int[] path : paths) {
            int nextX = current[0] + path[0];
            int nextY = current[1] + path[1];

            if (nextX >= 0 && nextX < n && nextY >= 0 && nextY < n && !visited[nextX][nextY]) {
                for (int[] direction : directions) {
                    if (path[0] == direction[0] && path[1] == direction[1]) {
                        visited[nextX][nextY] = true;
                        queue.offer(new int[]{nextX, nextY});
                        break;
                    }
                }
            }
        }
    }

    return "cannot be travelled";
}

