    }

    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], paths, visited);

    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }

    if (x < 0 || x >= visited.length || y < 0 || y >= visited[0].length || visited[x][y]) {
        return false;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        if ((path[0] == x && path[1] == y) || (path[1] == x && path[0] == y)) {
            if (dfs(path[0] == x ? path[1] : path[0], path[0] == x ? path[0] : path[1], endX, endY, paths, visited)) {
                return true;
            }
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            visited[i][j] = false;
        }
    }

    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    if (startX < 0 || startX >= n || startY < 0 || startY >= n || endX < 0 || endX >= n || endY < 0 || endY >= n) {
        return "cannot be travelled";
    }

    Map<String, List<int[]>> graph = new HashMap<>();
    for (int[] path : paths) {
        int fromX = path[0];
        int fromY = path[1];
        int toX = path[2];
        int toY = path[3];

        if (fromX < 0 || fromX >= n || fromY < 0 || fromY >= n || toX < 0 || toX >= n || toY < 0 || toY >= n) {
            continue;
        }

        String fromKey = fromX + "," + fromY;
        String toKey = toX + "," + toY;

        graph.computeIfAbsent(fromKey, k -> new ArrayList<>()).add(new int[]{toX, toY});
        graph.computeIfAbsent(toKey, k -> new ArrayList<>()).add(new int[]{fromX, fromY});
    }

    Queue<int[]> queue = new LinkedList<>();
    queue.offer(new int[]{startX, startY});
    visited[startX][startY] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int currentX = current[0];
        int currentY = current[1];

        if (currentX == endX && currentY == endY) {
            return "can be travelled";
        }

        String key = currentX + "," + currentY;
        if (graph.containsKey(key)) {
            for (int[] neighbor : graph.get(key)) {
                int neighborX = neighbor[0];
                int neighborY = neighbor[1];

                if (!visited[neighborX][neighborY]) {
                    visited[neighborX][neighborY] = true;
                    queue.offer(new int[]{neighborX, neighborY});
                }
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(n, start[0], start[1], end[0], end[1], paths, visited);

    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int n, int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }

    visited[x][y] = true;

    if (x == endX && y == endY) {
        return true;
    }

    for (int[] path : paths) {
        int newX = x + path[0];
        int newY = y + path[1];
        if (dfs(n, newX, newY, endX, endY, paths, visited)) {
            return true;
        }
    }

    return false;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    boolean[] usedLetters = new boolean[26];
    int commonCount = 0;

    for (char c : word1.toCharArray()) {
        if (word2.indexOf(c) != -1 && !usedLetters[c - 'A']) {
            commonCount++;
            usedLetters[c - 'A'] = true;
        }
    }

    int totalLength = word1.length() + word2.length();
    int gcd = gcd(commonCount, totalLength);

    return String.format("appx(%s, %s) = %d/%d", word1, word2, commonCount / gcd, totalLength / gcd);
}

private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

