    while (result.length() < length) {
        // Pick smallest characters in ascending order
        for (int i = 0; i < 26; i++) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
            }
        }

        // Pick largest characters in descending order
        for (int i = 25; i >= 0; i--) {
            if (charCount[i] > 0) {
                result.append((char) (i + 'a'));
                charCount[i]--;
            }
        }
    }

    return result.toString();
}

