public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    int n = nums.length;
    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i / 2, n / 2); j >= 1; j--) {
            for (int k = sum; k >= num; k--) {
                dp[i][j][k] = dp[i - 1][j][k] || dp[i - 1][j - 1][k - num];
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        if ((sum * j) % n == 0 && dp[n][j][(sum * j) / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length < 2) {
        return false;
    }

    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Precompute the GCD of n and sum
    int gcd = gcd(n, sum);
    int targetN = n / gcd;
    int targetSum = sum / gcd;

    // dp[i][j] means if we can find a subset of size i with sum j
    boolean[][] dp = new boolean[targetN + 1][targetSum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        // Traverse backwards to avoid overwriting results from the same iteration
        for (int i = targetN; i >= 1; i--) {
            for (int j = 0; j <= targetSum - num; j++) {
                dp[i][j + num] = dp[i][j + num] || dp[i - 1][j];
            }
        }
    }

    // Check if there exists a subset of size i (1 <= i < n) with sum j
    for (int i = 1; i <= n / 2; i++) {
        if (targetN * i <= n && dp[i][targetSum * i / n]) {
            return true;
        }
    }

    return false;
}

private int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

