public boolean hasAllCodes(String s, int k) {
    if (s == null || k < 0 || s.length() < k) {
        return false;
    }

    Set<String> seen = new HashSet<>();
    for (int i = 0; i <= s.length() - k; i++) {
        String substr = s.substring(i, i + k);
        seen.add(substr);
    }

    return seen.size() == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() == 0 || k <= 0) {
        return false;
    }

    int numDistinct = 1 << k; // 2^k possible binary strings of length k
    Set<String> foundCodes = new HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        String binaryString = s.substring(i, i + k);
        foundCodes.add(binaryString);
        if (foundCodes.size() == numDistinct) {
            return true;
        }
    }

    return foundCodes.size() == numDistinct;
}

