public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0 || s.length() < k) {
        return false;
    }

    int total = 1 << k; // 2^k
    boolean[] seen = new boolean[total];

    for (int i = 0; i <= s.length() - k; i++) {
        int val = 0;
        for (int j = 0; j < k; j++) {
            val = (val << 1) | (s.charAt(i + j) - '0');
        }
        seen[val] = true;
    }

    for (boolean b : seen) {
        if (!b) {
            return false;
        }
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() == 0 || k <= 0) {
        return false;
    }

    int need = 1 << k; // 2^k
    boolean[] seen = new boolean[need];
    int value = 0;
    int mask = need - 1; // 2^k - 1

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & mask | (s.charAt(i) - '0');
        if (i >= (k - 1) && !seen[value]) {
            seen[value] = true;
            need--;
        }
    }

    return need == 0;
}

