public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int openCount = 0; // To count the number of unmatched '('
    int insertions = 0; // To count the number of insertions needed

    for (char c : s.toCharArray()) {
        if (c == '(') {
            openCount++;
        } else if (c == ')') {
            if (openCount > 0) {
                openCount--;
            } else {
                insertions++; // Need to insert a matching '('
            }
            // Check for consecutive ')'
            if (c + 1 < s.length() && s.charAt(c + 1) == ')') {
                c++; // Skip the next ')'
            } else {
                insertions++; // Need to insert another ')' to make "))"
            }
        }
    }

    // Any unmatched '(' will need a corresponding ')'
    insertions += openCount * 2;

    return insertions;
}

public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }

    int openNeed = 0; // Number of '(' needed
    int insertions = 0; // Number of insertions made
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            openNeed += 2; // Each '(' needs two ')' to be balanced
            if (openNeed % 2 == 1) {
                insertions++; // Insert a ')' to make it even
                openNeed--; // This ')' balances one of the needed '('
            }
        } else if (s.charAt(i) == ')') {
            openNeed--;
            if (openNeed == -1) {
                insertions++; // Insert a '(' to balance this ')'
                openNeed = 1; // We need one more ')' now
            }
        }
        i++;
    }

    return insertions + openNeed; // Add remaining needed ')' to the result
}

public int minInsertions(String s) {
    int open = 0; // Count of open parentheses needed
    int close = 0; // Count of close parentheses needed
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            open++;
        } else {
            // If we encounter a ')', we need a matching '('
            if (open > 0) {
                open--; // Use one open parenthesis
            } else {
                close++; // Need to add an open parenthesis
            }
            // Each ')' should be followed by another ')' for proper pairing
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')' as it's part of the pair
            } else {
                close++; // Need to add a closing parenthesis
            }
        }
        i++;
    }

    // Total insertions needed is the sum of unmatched open and close parentheses
    return open + close;
}

