public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    // Generate all Fibonacci numbers less than or equal to k
    List<Integer> fibonacciNumbers = new ArrayList<>();
    int a = 1, b = 1;
    fibonacciNumbers.add(a);
    while (b <= k) {
        fibonacciNumbers.add(b);
        int next = a + b;
        a = b;
        b = next;
    }

    int count = 0;
    // Start from the largest Fibonacci number and work backwards
    for (int i = fibonacciNumbers.size() - 1; i >= 0 && k > 0; i--) {
        if (fibonacciNumbers.get(i) <= k) {
            k -= fibonacciNumbers.get(i);
            count++;
        }
    }

    return count;
}

public int findMinFibonacciNumbers(int k) {
