public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    return maxUniqueSplitHelper(s, 0, new HashSet<String>());
}

private int maxUniqueSplitHelper(String s, int start, Set<String> seen) {
    if (start == s.length()) {
        return 0;
    }
    int maxUnique = 0;
    for (int end = start + 1; end <= s.length(); end++) {
        String substr = s.substring(start, end);
        if (!seen.contains(substr)) {
            seen.add(substr);
            maxUnique = Math.max(maxUnique, 1 + maxUniqueSplitHelper(s, end, seen));
            seen.remove(substr);
        }
    }
    return maxUnique;
}

