public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    for (int i = 0; i <= 9; i++) {
        bfsSearch(low, high, i, result);
    }

    Collections.sort(result);
    return result;
}

private static void bfsSearch(int low, int high, int number, List<Integer> result) {
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(number);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current >= low && current <= high) {
            result.add(current);
        }
        if (current == 0 || current > high) {
            continue;
        }

        int lastDigit = current % 10;
        if (lastDigit > 0) {
            int nextNumber = current * 10 + (lastDigit - 1);
            if (nextNumber <= high) {
                queue.offer(nextNumber);
            }
        }
        if (lastDigit < 9) {
            int nextNumber = current * 10 + (lastDigit + 1);
            if (nextNumber <= high) {
                queue.offer(nextNumber);
            }
        }
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Add all single-digit numbers to the queue
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();

        // If the number is within the range, add it to the result list
        if (num >= low && num <= high) {
            result.add(num);
        }

        // If the number is 0 or greater than high/10, it cannot be the starting of a new stepping number
        if (num == 0 || num > high / 10) {
            continue;
        }

        int lastDigit = num % 10;

        // Generate the next stepping number by adding the last digit ± 1
        if (lastDigit > 0) {
            int nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
        if (lastDigit < 9) {
            int nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    // Sort the result list
    Collections.sort(result);
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low < 0 || high < 0 || low > high) {
        return result; // Return empty list for invalid input
    }

    for (int i = low; i <= Math.min(high, 9); i++) {
        result.add(i);
    }

    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }

        if (num >= low) {
            result.add(num);
        }

        int lastDigit = num % 10;
        int nextNum;

        if (lastDigit > 0) {
            nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.offer(nextNum);
            }
        }

        if (lastDigit < 9) {
            nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
