    }
    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        backtrack(result, i, low, high);
    }
    Collections.sort(result);
    return result;
}

private static void backtrack(List<Integer> result, int current, int low, int high) {
    if (current > high) {
        return;
    }
    if (current >= low) {
        result.add(current);
    }
    int lastDigit = current % 10;
    if (lastDigit > 0) {
        int next = current * 10 + (lastDigit - 1);
        backtrack(result, next, low, high);
    }
    if (lastDigit < 9) {
        int next = current * 10 + (lastDigit + 1);
        backtrack(result, next, low, high);
    }
}

