    backtrack(A, used, new ArrayList<>(), count);
    return count[0];
}

private static void backtrack(int[] A, boolean[] used, List<Integer> current, int[] count) {
    if (current.size() == A.length) {
        count[0]++;
        return;
    }

    Set<Integer> set = new HashSet<>();
    for (int i = 0; i < A.length; i++) {
        if (used[i] || (current.size() > 0 && set.contains(A[i]))) continue;

        if (current.isEmpty() || isPerfectSquare(current.get(current.size() - 1) + A[i])) {
            used[i] = true;
            current.add(A[i]);
            set.add(A[i]);
            backtrack(A, used, current, count);
            used[i] = false;
            current.remove(current.size() - 1);
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}

